using FinOS.Common.Models;using FinOS.CoreFinance.Application.Commands;using FinOS.CoreFinance.Application.Queries;using FinOS.CoreFinance.Domain.Entities;using MediatR;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace FinOS.CoreFinance.API.Controllers;
[ApiController,Route("api/assets"),Authorize]public class AssetsController(IMediator m):ControllerBase{long U=>long.Parse(User.FindFirst("sub")?.Value??User.FindFirst("userId")?.Value??"0");[HttpGet]public async Task<ApiResponse<IReadOnlyList<Asset>>>Get()=>ApiResponse<IReadOnlyList<Asset>>.Ok(await m.Send(new GetAssetsQuery(U)));[HttpPost]public async Task<ApiResponse<Asset>>Add(Asset x)=>ApiResponse<Asset>.Ok(await m.Send(new AddAssetCommand(U,x)));[HttpDelete("{id:long}")]public async Task<ApiResponse<object>>Delete(long id){await m.Send(new DeleteAssetCommand(U,id));return ApiResponse<object>.Ok(new{});}}
